import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../theme/app_theme.dart';
class DeviceInfoScreen extends StatefulWidget{const DeviceInfoScreen({super.key});@override State<DeviceInfoScreen>createState()=>_D();}
class _D extends State<DeviceInfoScreen>{Map<String,dynamic>? d;Future<void>load()async{final u=Supabase.instance.client.auth.currentUser;if(u!=null)d=await Supabase.instance.client.from('devices').select().eq('user_id',u.id).order('created_at',ascending:false).limit(1).maybeSingle();if(mounted)setState((){});}@override void initState(){super.initState();load();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Device Information')),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Column(children:[ListTile(title:const Text('Device Name'),trailing:Text('${d?['device_name']??'-'}')),ListTile(title:const Text('Model'),trailing:Text('${d?['model']??'-'}')),ListTile(title:const Text('Android Version'),trailing:Text('${d?['android_version']??'-'}')),ListTile(title:const Text('Status'),trailing:Text('${d?['status']??'-'}',style:const TextStyle(color:AppTheme.green))),ListTile(title:const Text('Last Seen'),trailing:Text('${d?['last_seen_at']??'-'}'))]))]));}
